const MONTHS = ["Jan", "Feb", "Mar", "Apr", "May", "Jun", "Jul", "Aug", "Sep", "Oct", "Nov", "Dec"];
const fmtDate = (d: Date) => `${MONTHS[d.getMonth()]} ${d.getDate()}, ${d.getFullYear()}`;

interface TimelineWeek {
	value: string;
	/** Week number shown on the tick (unless it starts a month). */
	num: number;
	start: Date;
	end: Date;
	/** True when this week begins a new month — the tick shows the month name instead of the number. */
	monthStart: boolean;
	monthLabel: string;
}

/**
 * Weekly reality-capture runs — one tick per week. Week 122 is the current Sep 5–11, 2026 window. Dates
 * are generated from that anchor so month boundaries (the first week that starts a new month) can be
 * flagged; those ticks render the month name in place of the week number.
 */
const TIMELINE_WEEKS_DEFAULT: TimelineWeek[] = (() => {
	const anchor = new Date(2026, 8, 5); // week 122 start (Sep 5, 2026)
	const anchorNum = 122;
	const DAY = 86_400_000;
	const raw = [] as {value: string; num: number; start: Date; end: Date}[];
	// The timeline ends at next week (anchor + 1); this week (122) is the default selection.
	for (let n = 88; n <= anchorNum + 1; n++) {
		const start = new Date(anchor.getTime() + (n - anchorNum) * 7 * DAY);
		raw.push({value: String(n), num: n, start, end: new Date(start.getTime() + 6 * DAY)});
	}
	return raw.map((w, i) => ({
		...w,
		monthStart: i > 0 && w.start.getMonth() !== raw[i - 1].start.getMonth(),
		monthLabel: MONTHS[w.start.getMonth()],
	}));
})();

type Villa = {
	/** Stable unique id (the fixture villa id as a string). */
	id: string;
	/** Display name, e.g. "2279 VL6-L". */
	name: string;
	meta: string;
	/** Approved progress, 0–100. */
	approved: number;
	/** Planned progress, 0–100. */
	planned: number;
};

/** Map a villa name's type code to a human label (e.g. "2279 VL6-L" → "Villa"). */
const VILLA_TYPE_LABELS: Record<string, string> = {
	TH: "Townhouse",
	DT: "Detached",
	VL: "Villa",
	VD: "Villa Duplex",
	DP: "Duplex",
};

function villaTypeLabel(name: string) {
	const code = name.match(/[A-Z]{2}/)?.[0];
	return (code && VILLA_TYPE_LABELS[code]) || "Unit";
}

/** Map SiteImageViewer villa footprints to the left-rail row shape, so the list matches what's drawn. */
function villaRows(villas: SiteVilla[]): Villa[] {
	return villas.map((v) => ({
		id: String(v.id),
		name: v.name,
		meta: `${villaTypeLabel(v.name)} · Plot ${v.plotNumber}`,
		approved: Math.round(v.approvedProgressPercent ?? 0),
		planned: Math.round(v.plannedProgressPercent ?? 0),
	}));
}

