/**
 * Distribution over the SiteImageViewer's ramps — the same buckets, labels, and colours the map polygons
 * + legend use, with each bucket's real count for the given rows. SPA = milestone ramp (M35…M100 by
 * approved %), Construction = variance (behind / on-track / ahead of plan). Works for either level.
 */
function distributionFor(rows: Villa[], mode: MapMode) {
	if (mode === "variance") {
		return VARIANCE_LEGEND_ITEMS.filter((item) => ["behind", "onTrack", "ahead"].includes(item.id)).map((b) => ({
			id: b.id,
			label: b.label,
			range: b.description,
			color: b.color,
			count: rows.filter((v) => classifyVariance(v.approved, v.planned) === b.id).length,
		}));
	}
	return PROGRESS_LEGEND_ITEMS.filter((item) => item.id.startsWith("ms")).map((b) => ({
		id: b.id,
		label: b.label,
		range: b.description,
		color: b.color,
		count: rows.filter((v) => approvedProgressToBucket(v.approved) === b.id).length,
	}));
}

