/**
 * The site tree for the CanvasNavigator — the real Al Manar hierarchy from `almanar-hierarchy-data`:
 * Phase 1 (the header) → Zone → Batch → Villa (blocks + construction systems collapsed away). Villa leaves
 * resolve to their app row id so selecting one opens that villa; `NAV_VILLA_ZONE` records each leaf's zone.
 */
const rowByNumber = (villas: SiteVilla[]) => {
	const m = new Map<string, SiteVilla>();
	for (const v of villas) {
		const n = v.name.match(/^\d+/)?.[0];
		if (n && !m.has(n)) m.set(n, v);
	}
	return m;
};
const ROW_BY_NUMBER: Record<string, Map<string, SiteVilla>> = {
	"zone-1-a": rowByNumber(ALMANAR_VILLAS),
	"zone-1-b": rowByNumber(ALMANAR_ZONE_B_VILLAS),
};
/** Villa row id → its zone, so the navigator's onSelect can switch to the right zone before opening it. */
const NAV_VILLA_ZONE_DEFAULT = new Map<string, string>();
// Group a batch's villas by their block (ROSHN nests Zone → Batch → BLOCK → Villa). Villas with no captured
// block record fall into a trailing "Unassigned" group so none are dropped. Blocks sort numerically.
function blockNodesForBatch(loc: string, batchName: string, villaNumbers: string[]): CanvasNavigatorNode[] {
	const groups = new Map<string, {block: string; villas: CanvasNavigatorNode[]}>();
	const order: string[] = [];
	for (const num of villaNumbers) {
		const v = ROW_BY_NUMBER[loc]?.get(num);
		if (!v) continue;
		const id = String(v.id);
		NAV_VILLA_ZONE_DEFAULT.set(id, loc);
		const block = ALMANAR_VILLA_BLOCK[num] ?? "";
		const key = block || "unassigned";
		let group = groups.get(key);
		if (!group) {
			group = {block, villas: []};
			groups.set(key, group);
			order.push(key);
		}
		group.villas.push({id, label: v.name, icon: <Home className="wwc:size-4" />});
	}
	order.sort((a, b) => {
		if (a === "unassigned") return 1;
		if (b === "unassigned") return -1;
		return Number(a) - Number(b);
	});
	return order.map((key) => {
		const group = groups.get(key) ?? {block: "", villas: []};
		return {
			id: `block::${loc}::${batchName}::${key}`,
			label: group.block ? `Block ${group.block}` : "Unassigned",
			icon: <Boxes className="wwc:size-4" />,
			children: group.villas,
		};
	});
}
const NAV_NODES_DEFAULT: CanvasNavigatorNode[] = LOCATIONS.map((loc) => ({
	id: loc.id,
	label: loc.label,
	icon: <MapIcon className="wwc:size-4" />,
	children: (ALMANAR_HIERARCHY[loc.id] ?? []).map((batch) => ({
		id: `batch::${loc.id}::${batch.name}`,
		label: batch.units ? `${batch.name} · ${batch.units} units` : batch.name,
		icon: <LayoutGrid className="wwc:size-4" />,
		children: blockNodesForBatch(loc.id, batch.name, batch.villaNumbers),
	})),
}));

/**
 * Map a zone polygon's `id` → its `ZONE_VILLA_VIEWS` location, so clicking a zone on the map drills into the
 * matching zone's villas (not always Zone 1-A). Built from every zone-level dataset (marketing + satellite),
 * keyed on the same id the rows use; the trailing "A"/"B" of the name picks the location.
 */
const ZONE_LOCATION_BY_ID: Record<string, string> = {};
for (const z of [...ALMANAR_ZONES_MARKETING, ...ALMANAR_ZONES]) {
	const last = z.name.trim().slice(-1).toLowerCase();
	const loc = last === "a" ? "zone-1-a" : last === "b" ? "zone-1-b" : null;
	if (loc) ZONE_LOCATION_BY_ID[String(z.linkedLbsItemId ?? z.id)] = loc;
}

